#!/usr/bin/env python3
"""FS3 v204 - 3D finishing work: hit where the model is, damage on the model,
debris in its layer, the Pharos in 3D.

    Hits       Fighters, bombers and the player are hit on the outline of
               their model as it is drawn - rolled and banked (one map per
               sixteenth of a roll, built from the model when first needed).
    Damage     Scoring, tears, craters and the hot edges of a ship drawn from
               her model lie on her model: they turn with her and are hidden
               by a hull in front (M38: the Deimos' damage no longer shows on
               the Elysium).
    Debris     The pieces of a ship that broke up stay in her layer: in front
               of what lay behind her (M11: the Typhon's pieces in front of
               the Arcadia).
    Pharos     The GTNB Pharos is drawn from the MediaVPs' nav buoy.

Needs v203. Edits src/20_render.js, 50_combat.js, 58_model3d.js,
59_field3d.js, 70_ui.js and fieldsim.js. New model file:
models_v204.zip (the Pharos).
Run assemble.py 204 afterwards.
"""
import base64
import os
import sys

if not os.path.exists("src/59_field3d.js"):
    sys.exit("Abbruch: erst v203 einspielen.")
_f = open("src/59_field3d.js", encoding="utf-8").read()
if "F3D_SMALL" not in _f:
    sys.exit("Abbruch: erst v203 einspielen.")
if "f3dRollMask" in _f:
    sys.exit("Abbruch: v204 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
